function looseEquals(a, b) {
  if (typeof a === typeof b) return a === b;
  // null and undefined only equal each other
  if ((a === null && b === undefined) || (a === undefined && b === null)) return true;
  if (a === null || a === undefined || b === null || b === undefined) return false;
  // booleans coerce to numbers
  if (typeof a === 'boolean') return looseEquals(Number(a), b);
  if (typeof b === 'boolean') return looseEquals(a, Number(b));
  // number vs string: coerce string to number
  if (typeof a === 'number' && typeof b === 'string') return a === Number(b);
  if (typeof a === 'string' && typeof b === 'number') return Number(a) === b;
  return false;
}

console.log(looseEquals(1, '1'));        // true
console.log(looseEquals(true, 1));       // true
console.log(looseEquals(null, undefined)); // true
console.log(looseEquals('', 0));         // true
console.log(looseEquals(0, false));      // true
